class CartoonHomeOverlay(QWidget):
    BASE_WIDTH = 1368
    BASE_HEIGHT = 714

    # Coordinates in the supplied image, after removing the 24-pixel titlebar.
    HOTSPOTS = (
        ("estudo", "Iniciar Estudo", (120, 347, 416, 221)),
        ("dashboard", "Dashboard", (555, 347, 371, 221)),
        ("edital", "Meu Edital", (947, 347, 366, 221)),
        ("perfil", "Perfil ativo", (1034, 23, 281, 58)),
        ("inicio", "Início", (9, 78, 50, 49)),
        ("recursos", "Central de Recursos", (9, 131, 50, 49)),
        ("disciplinas", "Disciplinas", (9, 186, 50, 48)),
        ("planejamento", "Planejamento", (9, 241, 50, 49)),
        ("analises", "Central de Análises", (9, 295, 50, 49)),
        ("pausa", "Pausa e Desafios", (9, 350, 50, 48)),
        ("concursos", "Gerenciar perfis", (9, 406, 50, 47)),
        ("perfil_candidato", "Perfil do Candidato", (9, 556, 50, 44)),
        ("pesquisa", "Pesquisar", (9, 605, 50, 48)),
        ("configuracoes", "Configurações", (9, 657, 50, 49)),
    )

    def __init__(self, parent, actions, profile_name, state_changed=None):
        super().__init__(parent)
        self.setObjectName("homeCartoonH40Overlay")
        self._actions = dict(actions)
        self._profile_name = profile_name
        self._state_changed = state_changed
        self._settings = QSettings("VighnaStudy", "HomeCartoonH40Teste")
        setting = self._settings.value("cartoon_enabled", True)
        self.cartoon_enabled = str(setting).strip().lower() not in ("false", "0", "no", "off")
        self.setAttribute(Qt.WA_OpaquePaintEvent)
        self.setAutoFillBackground(False)
        self.setFocusPolicy(Qt.NoFocus)
        self._pixmap = QPixmap()
        if not self._pixmap.loadFromData(base64.b85decode(_CARTOON_ART), "PNG"):
            raise RuntimeError("Falha ao carregar a arte da Home cartoon")
        self._buttons = []
        for key, tooltip, coords in self.HOTSPOTS:
            button = QPushButton("", self)
            button.setObjectName("homeCartoonHotspot_" + key)
            button.setToolTip(tooltip)
            button.setAccessibleName(tooltip)
            button.setCursor(Qt.PointingHandCursor)
            button.setFocusPolicy(Qt.StrongFocus)
            button.setStyleSheet(
                'QPushButton {background:transparent;border:1px solid transparent;}'
                'QPushButton:hover {background:rgba(255,255,255,0.045);border:2px solid rgba(99,207,245,0.55);border-radius:14px;}'
                'QPushButton:focus {border:2px solid #f0bc61;border-radius:14px;}'
            )
            fn = self._actions.get(key)
            if fn is not None:
                button.clicked.connect(lambda _checked=False, action=fn: action())
            self._buttons.append((button, coords))

        self._original_button = QPushButton("Visual original", self)
        self._original_button.setToolTip("Desativar Home cartoon (Ctrl+Alt+C)")
        self._original_button.setAccessibleName("Voltar à Home original")
        self._original_button.setCursor(Qt.PointingHandCursor)
        self._original_button.setFocusPolicy(Qt.StrongFocus)
        self._original_button.setStyleSheet(
            'QPushButton {color:#ffffff;background-color:rgba(21,54,85,0.85);'
            'border:1px solid #7abbd5;border-radius:9px;padding:4px 10px;'
            'font-size:10pt;font-weight:600;}'
            'QPushButton:hover {background-color:#29628a;border-color:#f5c86f;}'
        )
        self._original_button.clicked.connect(lambda _checked=False: self.toggle())
        parent.installEventFilter(self)
        self.setGeometry(parent.rect())
        self._layout_buttons()
        self.setVisible(self.cartoon_enabled)
        self.raise_()

    def _geometry(self):
        scale = min(max(1,self.width()) / self.BASE_WIDTH,
                    max(1,self.height()) / self.BASE_HEIGHT)
        scaled_w = self.BASE_WIDTH * scale
        scaled_h = self.BASE_HEIGHT * scale
        return scale, (self.width() - scaled_w) * .5, (self.height() - scaled_h) * .5

    def _layout_buttons(self):
        scale, dx, dy = self._geometry()
        for btn, (x,y,w,h) in self._buttons:
            btn.setGeometry(round(dx+x*scale),round(dy+y*scale),
                            max(1,round(w*scale)),max(1,round(h*scale)))
        self._original_button.setGeometry(round(dx+1154*scale),
                                           round(dy+668*scale),
                                           max(110,round(155*scale)),
                                           max(27,round(32*scale)))

    def eventFilter(self, watched, event):
        if watched is self.parentWidget() and event.type() in (QEvent.Resize, QEvent.Show):
            self.setGeometry(self.parentWidget().rect())
            self.raise_()
            self._layout_buttons()
        return super().eventFilter(watched,event)

    def resizeEvent(self,event):
        super().resizeEvent(event)
        self._layout_buttons()

    def toggle(self):
        self.cartoon_enabled = not self.cartoon_enabled
        self._settings.setValue("cartoon_enabled",self.cartoon_enabled)
        self.setVisible(self.cartoon_enabled)
        if self.cartoon_enabled:
            self.raise_()
        if self._state_changed is not None:
            self._state_changed()
        return self.cartoon_enabled

    def paintEvent(self,event):
        painter=QPainter(self)
        painter.setRenderHint(QPainter.SmoothPixmapTransform, True)
        painter.fillRect(self.rect(), QColor('#0b335a'))
        scale,dx,dy=self._geometry()
        painter.drawPixmap(QRectF(dx,dy,self.BASE_WIDTH*scale,self.BASE_HEIGHT*scale),
                           self._pixmap,QRectF(self._pixmap.rect()))
        # Profile name remains live, instead of the name baked into the reference.
        r=QRectF(dx+1035*scale,dy+22*scale,280*scale,57*scale)
        painter.setPen(QPen(QColor('#60748b'),max(1,1.4*scale)))
        painter.setBrush(QColor('#294360'))
        painter.drawRoundedRect(r,13*scale,13*scale)
        text='▣ ' + (str(self._profile_name() or '').strip() or 'Perfil ativo')
        font=QFont('Segoe UI',max(8,round(13*scale)))
        font.setBold(False)
        painter.setFont(font)
        painter.setPen(QColor('#ffffff'))
        painter.drawText(r.adjusted(14*scale,0,-10*scale,0),
                         Qt.AlignVCenter|Qt.AlignLeft,text)
        painter.end()
